<script lang="ts">
 import { page } from "$app/state";
 import { PUBLIC_SITE_NAME } from "$env/static/public";
 import { Constants, Utils } from "$lib";
 import MangaEdit from "$publicApi/PublicTitleEditor.svelte";
 import ErrorComponent from "$lib/components/ErrorComponent.svelte";
 import { buttonVariants } from "$lib/components/ui/button";
 import * as Empty from "$lib/components/ui/empty";
 import NotFound from "$lib/components/ui/NotFound.svelte";
 import { Spinner } from "$lib/components/ui/spinner";
 import { from } from "$lib/stores";
 import { ArrowLeftIcon } from "@lucide/svelte";
 // The signed loader supplies the actual title. PublicTitleEditor owns the
 // current account, title read and signed cover lifecycle; native cookie
 // private-feed/cover readers cannot authorize or hydrate this UUID route.
 const { data }: { data: { manga?: Manga } } = $props();
 const isMounted = true;
 const error: Constants.Error.Error | undefined = undefined;
 const covers: unknown[] | undefined = undefined;
</script>

<svelte:head>
	{#if data.manga}
		<title>Edit: {data.manga.title} - {PUBLIC_SITE_NAME}</title>
	{/if}
</svelte:head>

{#if error}
	<ErrorComponent {error} />
{:else if isMounted}
	{#if data.manga}
		<section class="mx-auto flex w-full max-w-270 flex-auto flex-col space-y-5">
			<header class="flex items-center gap-2">
				{#if data.manga.state === Constants.State.Published}
					<a
						class={buttonVariants({ class: "rounded-full", variant: "ghost", size: "icon" })}
						href={$from && !$from.pathname.startsWith("/create") && !$from.pathname.endsWith("/edit")
							? $from.href
							: `/title/${data.manga.id}${Utils.makeSlug(data.manga.title)}`}
					>
						<ArrowLeftIcon class="size-5" />
					</a>
				{:else}
					<a
						class={buttonVariants({ class: "rounded-full", variant: "ghost", size: "icon" })}
						href={$from && !$from.pathname.startsWith("/create") && !$from.pathname.endsWith("/edit")
							? $from.href
							: "/drafts/title"}
					>
						<ArrowLeftIcon class="size-5" />
					</a>
				{/if}
				<h2 class="text-xl font-medium">Edit Title</h2>
			</header>
			{#key [page.url.pathname, data.manga.id].join(":")}
				<MangaEdit data={{ manga: data.manga, covers }} />
			{/key}
		</section>
	{:else}
		<NotFound />
	{/if}
{:else}
	<Empty.Root>
		<Spinner class="size-10" />
	</Empty.Root>
{/if}
